-- JHub protected build
local tY6uf_M = "7vjWdnBRQFreACY9af2G3DUESKx4ZbOmTzskJ/6wgM5IHP8oclLiqhtuX+Np10yV"
local bSQeou7 = {
    k5pDmjp = "",
    fJqjtYX = "",
    vstSTPx = "",
    oorye5M = "",
}
local kJQQIzq = {
    "vstSTPx", "k5pDmjp", "oorye5M", "fJqjtYX"
}
local dVKnS7q = {
    {s = "7CJamlNJTZx3fL", w = "TF92uUtGQbzUM3XVnf5MyOpDzIMQ98BiiDMKcFIiu4H="},
    {s = "UbbPaFfezvSsgI", w = "3TTwYqDS9Qhl01MN6SCW3Ux9mGfNmpeQqeYeedo98Jq="},
    {s = "0T9r1n5KfTRzFg", w = "NMmf7ATUruIQEfyhB9s9hXArdNZXiZ0cmf6ED6n9Vj3="},
    {s = "RaiHYpfu4IHeti", w = "xBwh4J7bvHt2D1w17dU1Vy4m0t9QQZP27R+MTefbZ5q="},
    {s = "E2HfqUQFMsnRFC", w = "ysMueYCTuU5eO7gVLyTj/lxomWHrf3gwBuDIqrZpHhq="},
    {s = "MntHk5rLG6MKcP", w = "c2720UeySqHUbvNiF14l/UqqJIpnKpYRs4EoBt+U5/g="},
    {s = "NjgGRmXd4ydijV", w = "hdT+3uny0OA0JqklccbbXFUE4jLHrOoPS+y9A7tGw8S="},
    {s = "vzJ0FPPVI8djYU", w = "47o9x6bHpVkjN7XsgQ8aTL8PHkVtLeIsjqXIo0wOgxJ="},
    {s = "M6cMKEy546Soms", w = "+29dXOaaCeVSOPW9Lj1RsK/bEfOpxzS7nri3XMkXCb7="},
    {s = "uFX9dGS8BCQmVL", w = "ThUulq+OCwWc/Vye+KmUkhudWMtQk8qyrdQUmOoomGd="},
    {s = "dCvs3HTLMYZwfe", w = "l4gl+GqBWxZ7N2xCMaz9vM8t+aCigqkT/fcULWyqQa7="},
    {s = "SUJwcg0r9jo6G4", w = "ueqTA5BrjANSpUe3MB5Ttna9hPBs7r6isx1ioqaU0hJ="},
}
local apX6Ld6 = 1559927053
local iRIx7K3 = 3474787609
local cPo6A5o = "JHub/PB/jhub.key"

local function b64decode(s, alphabet)
    local rev = {}
    for i = 1, 64 do
        rev[string.byte(alphabet, i)] = i - 1
    end
    local EQ = string.byte("=")
    local len = #s
    while len > 0 and string.byte(s, len) == EQ do
        len -= 1
    end
    local outLen = (len * 6) // 8
    local buf = buffer.create(outLen)
    local acc, bits, pos = 0, 0, 0
    for i = 1, len do
        local v = rev[string.byte(s, i)]
        acc = acc * 64 + v
        bits += 6
        if bits >= 8 then
            bits -= 8
            local denom = 2 ^ bits
            local shifted = acc // denom
            buffer.writeu8(buf, pos, shifted % 256)
            pos += 1
            acc = acc % denom
        end
    end
    return buffer.tostring(buf)
end

local function mulmod32(a, b)
    local a16 = a // 65536
    local a0 = a % 65536
    local hi = (a16 * b) % 4294967296
    local lo = (a0 * b) % 4294967296
    return (hi * 65536 + lo) % 4294967296
end

local function fnv1a32(s)
    local h = 2166136261
    for i = 1, #s do
        h = bit32.bxor(h, string.byte(s, i))
        h = mulmod32(h, 16777619)
    end
    return h
end

local function xorshift32Next(state)
    state = bit32.bxor(state, bit32.lshift(state, 13))
    state = bit32.bxor(state, bit32.rshift(state, 17))
    state = bit32.bxor(state, bit32.lshift(state, 5))
    return state
end

local function seedFrom(s)
    local h = fnv1a32(s)
    if h == 0 then h = 1 end
    return h
end

local function xorStream(data, seedStr)
    local n = #data
    local src = buffer.create(n)
    buffer.writestring(src, 0, data)
    local out = buffer.create(n)
    local state = seedFrom(seedStr)
    local i = 0
    while i < n do
        state = xorshift32Next(state)
        local b0 = (state // 16777216) % 256
        local b1 = (state // 65536) % 256
        local b2 = (state // 256) % 256
        local b3 = state % 256
        local bytes4 = {b0, b1, b2, b3}
        for k = 1, 4 do
            if i >= n then break end
            local orig = buffer.readu8(src, i)
            buffer.writeu8(out, i, bit32.bxor(orig, bytes4[k]))
            i += 1
        end
    end
    return buffer.tostring(out)
end

local function normKey(s)
    return string.lower((string.gsub(s or "", "%s+", "")))
end

-- Tries to unwrap the master secret M using the given raw key input.
-- Returns M (as a raw byte string) on success, or nil on failure.
-- This is the actual cryptographic gate: without a valid key there is no
-- way to derive M, and without M there is no way to derive the chunk
-- decrypt keystreams -- decoding itself requires a real key now.
local function attemptUnlock(raw)
    local norm = normKey(raw)
    if norm == "" then
        return nil
    end
    for _, entry in ipairs(dVKnS7q) do
        local wrapped = b64decode(entry.w, tY6uf_M)
        local seedStr = norm .. "|" .. entry.s
        local candidate = xorStream(wrapped, seedStr)
        if fnv1a32(candidate) == apX6Ld6 and fnv1a32("check2|" .. candidate) == iRIx7K3 then
            return candidate
        end
    end
    return nil
end

local function reconstruct(M)
    local parts = table.create(#kJQQIzq)
    for i, name in ipairs(kJQQIzq) do
        local raw = b64decode(bSQeou7[name], tY6uf_M)
        local seedStr = M .. "|" .. tostring(i)
        parts[i] = xorStream(raw, seedStr)
    end
    return table.concat(parts)
end

local function saveKey(norm)
    pcall(function()
        if not isfolder("JHub") then makefolder("JHub") end
        if not isfolder("JHub/PB") then makefolder("JHub/PB") end
        writefile(cPo6A5o, norm)
    end)
end

local function promptKey(onUnlocked)
    local okCore, CoreGui = pcall(function() return game:GetService("CoreGui") end)
    local gui = Instance.new("ScreenGui")
    gui.Name = "JHubKeyGate"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    local parented = false
    if okCore then
        parented = pcall(function() gui.Parent = CoreGui end)
    end
    if not parented then
        local lp = game:GetService("Players").LocalPlayer
        pcall(function() gui.Parent = lp:WaitForChild("PlayerGui", 10) end)
    end

    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(0, 320, 0, 170)
    frame.Position = UDim2.new(0.5, -160, 0.5, -85)
    frame.BackgroundColor3 = Color3.fromRGB(24, 24, 28)
    frame.BorderSizePixel = 0
    frame.Parent = gui
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 10)
    corner.Parent = frame

    local title = Instance.new("TextLabel")
    title.Text = "JHub - Enter your key"
    title.Size = UDim2.new(1, -20, 0, 30)
    title.Position = UDim2.new(0, 10, 0, 12)
    title.BackgroundTransparency = 1
    title.TextColor3 = Color3.fromRGB(255, 255, 255)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 18
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = frame

    local box = Instance.new("TextBox")
    box.Size = UDim2.new(1, -20, 0, 36)
    box.Position = UDim2.new(0, 10, 0, 50)
    box.PlaceholderText = "Key"
    box.Text = ""
    box.ClearTextOnFocus = false
    box.BackgroundColor3 = Color3.fromRGB(40, 40, 46)
    box.TextColor3 = Color3.fromRGB(255, 255, 255)
    box.Font = Enum.Font.Gotham
    box.TextSize = 16
    box.Parent = frame
    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 6)
    boxCorner.Parent = box

    local errLabel = Instance.new("TextLabel")
    errLabel.Size = UDim2.new(1, -20, 0, 20)
    errLabel.Position = UDim2.new(0, 10, 0, 90)
    errLabel.BackgroundTransparency = 1
    errLabel.Text = ""
    errLabel.TextColor3 = Color3.fromRGB(255, 90, 90)
    errLabel.Font = Enum.Font.Gotham
    errLabel.TextSize = 13
    errLabel.TextXAlignment = Enum.TextXAlignment.Left
    errLabel.Parent = frame

    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, -20, 0, 34)
    btn.Position = UDim2.new(0, 10, 0, 118)
    btn.Text = "Unlock"
    btn.BackgroundColor3 = Color3.fromRGB(70, 120, 255)
    btn.TextColor3 = Color3.fromRGB(255, 255, 255)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 16
    btn.AutoButtonColor = true
    btn.Parent = frame
    local btnCorner = Instance.new("UICorner")
    btnCorner.CornerRadius = UDim.new(0, 6)
    btnCorner.Parent = btn

    local busy = false
    local function attempt()
        if busy then
            return
        end
        local text = box.Text
        local M = attemptUnlock(text)
        if M then
            busy = true
            saveKey(normKey(text))
            pcall(function() gui:Destroy() end)
            onUnlocked(M)
        else
            errLabel.Text = "Invalid key - try again"
        end
    end
    btn.MouseButton1Click:Connect(attempt)
    box.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            attempt()
        end
    end)
end

local function start(...)
    local n = select("#", ...)
    local args = table.pack(...)
    local function proceedWith(M)
        local src = reconstruct(M)
        local chunkFn, err = loadstring(src, "JHub")
        if not chunkFn then
            warn("[JHub] protected payload failed to compile: " .. tostring(err))
            return
        end
        return chunkFn(table.unpack(args, 1, n))
    end

    local storedOk, storedRaw = pcall(readfile, cPo6A5o)
    if storedOk and type(storedRaw) == "string" then
        local M = attemptUnlock(storedRaw)
        if M then
            return proceedWith(M)
        end
    end
    promptKey(proceedWith)
end

return start(...)
